// seed: tests/seed.spec.ts (гость) · прод, только чтение. Первый визит — service worker выключен.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, LOAD } from './whatsapp.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('WhatsApp למוכר — короткая ссылка /b/<код>', () => {
  for (const device of ['@desktop', '@android']) {
    test(`Без service worker неверный код /b/<код> → главная, не пустая страница #1d8184 ${device} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      for (const code of ['00000000', 'zzz']) {
        await page.goto('/b/' + code);
        await page.waitForURL((u) => u.pathname === '/', LOAD);
        await expect(page, `/b/${code}: не 404`).not.toHaveTitle(/הדף לא נמצא/);
        await expect(page.getByRole('heading', { name: 'זירת העסקים של ישראל' }), `/b/${code}: содержимое главной`).toBeVisible(LOAD);
      }
    });
  }
});
